import itertools

def F(x, y, z, a, b, c):
    return abs(x + y - a - b) + abs(y + z - b - c) + abs(z + x - c - a)

# Define queries
queries = {
    "Q1": (0, 0, 0),
    "Q2": (9, 9, 9),
    "Q3": (5, 5, 5)
}

# Dictionary to store the results: key is the tuple (F1, F2, F3), value is a list of (x, y, z) that yield this result
result_map = {}

# Iterate over all 1000 possible triples (x, y, z)
for x in range(10):
    for y in range(10):
        for z in range(10):
            triple = (x, y, z)

            # Calculate F values for the three queries
            f1 = F(x, y, z, *queries["Q1"])
            f2 = F(x, y, z, *queries["Q2"])
            f3 = F(x, y, z, *queries["Q3"])

            result_key = (f1, f2, f3)

            if result_key not in result_map:
                result_map[result_key] = []

            result_map[result_key].append(triple)

# Identify results that are ambiguous (more than one triple maps to the same result_key)
ambiguous_results = {key: list_of_triples for key, list_of_triples in result_map.items() if len(list_of_triples) > 1}

print(f"Total unique result keys found: {len(result_map)}")
print(f"Number of ambiguous result keys: {len(ambiguous_results)}")

if ambiguous_results:
    print("\n--- Ambiguous Results (Pairs/Groups of non-unique triples) ---")
    # Print the first 5 ambiguous results found for brevity
    count = 0
    for key, triples in ambiguous_results.items():
        if count >= 5:
            break
        print(f"Key: {key} -> Triples: {triples}")
        count += 1
else:
    print("\nNo ambiguous results found for these three queries.")

def V(x, y, z, a, b, c):
    return abs(x + y - a - b) + abs(y + z - b - c) + abs(z + x - c - a)

# Test K=1 query Q = (0, 0, 0)
Q_a, Q_b, Q_c = 0, 0, 0
results = {}
inputs = []

# Test for x, y, z in {0, 1, 2} (27 inputs)
for x in range(3):
    for y in range(3):
        for z in range(3):
            val = V(x, y, z, Q_a, Q_b, Q_c)
            results[val] = results.get(val, []) + [(x, y, z)]
            inputs.append((x, y, z))

# Check if any result maps to multiple inputs
collision_found = False
for val, inputs_list in results.items():
    if len(inputs_list) > 1:
        collision_found = True
        print(f"Collision found for V={val}: {inputs_list}")
        break

if not collision_found:
    print("No collision found for K=1 with range 0..2.")
else:
