def calculate_f1(x, y, z):
    # Q1 = (0, 0, 0)
    # F1 = |x+y| + |y+z| + |z+x|
    return abs(x + y) + abs(y + z) + abs(z + x)

def calculate_f2(x, y, z):
    # Q2 = (9, 9, 9)
    # F2 = |x+y-18| + |y+z-18| + |z+x-18|
    return abs(x + y - 18) + abs(y + z - 18) + abs(z + x - 18)

# Dictionary to store mappings: (F1, F2) -> list of (x, y, z)
result_map = {}
count = 0

